		'No smoking: it is the single biggest risk to integration' => 'Nada de tabaco: es el mayor riesgo para la integración',
		'Can a hybrid zirconium prosthesis be repaired if damaged?' => '¿Se puede reparar una prótesis híbrida de circonio si se daña?',
		'Final shape and density. Trimming continues indefinitely.' => 'Forma y densidad definitivas. El recorte, en cambio, no termina.',
		'Scarring alopecias ruled out before surgery is considered' => 'Se descartan las alopecias cicatriciales antes de plantear la cirugía',
		'Can implants be placed at the same time as the sinus lift?' => '¿Se pueden colocar los implantes a la vez que la elevación de seno?',
